import { forwardRef, type AnchorHTMLAttributes } from 'react';
export interface ActionLinkProps extends AnchorHTMLAttributes<HTMLAnchorElement> {
  /** External navigation uses a distinct diagonal arrow. */
  external?: boolean;
  arrow?: boolean;
}
/** Consistent text action with an opt-in SVG navigation cue. */
export const ActionLink = forwardRef<HTMLAnchorElement, ActionLinkProps>(function ActionLink(
  { external = false, arrow = true, children, className, target, rel, ...props }, ref,
) {
  return <a {...props} ref={ref} className={['cs-action-link', className].filter(Boolean).join(' ')} target={target ?? (external ? '_blank' : undefined)} rel={rel ?? (external || target === '_blank' ? 'noopener noreferrer' : undefined)}>
    <span>{children}</span>
    {arrow && <svg className="cs-action-link-arrow" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d={external ? 'M7 17 17 7M7 7h10v10' : 'M5 12h14m-5-5 5 5-5 5'} />
    </svg>}
  </a>;
});

"use client";
import { useEffect, useRef, useState } from 'react';

function RollingDigit({ digit, active }: { digit: number; active: boolean }) {
  const track = useRef<HTMLSpanElement>(null);
  const motion = useRef({ position: 0, velocity: 0 });
  useEffect(() => {
    const media = window.matchMedia?.('(prefers-reduced-motion: reduce)');
    const target = active ? digit : 0;
    let frame = 0;
    let previous = performance.now();
    const paint = () => {
      if (track.current) track.current.style.transform = `translateY(${-motion.current.position}em)`;
    };
    const snap = () => { cancelAnimationFrame(frame); motion.current = { position: target, velocity: 0 }; paint(); };
    if (media?.matches) { snap(); return; }
    const tick = (now: number) => {
      const dt = Math.min((now - previous) / 1000, 0.04);
      previous = now;
      // Exact critically damped spring step; re-targeting retains position and velocity.
      const omega = 18;
      const offset = motion.current.position - target;
      const combined = motion.current.velocity + omega * offset;
      const decay = Math.exp(-omega * dt);
      motion.current.position = target + (offset + combined * dt) * decay;
      motion.current.velocity = (motion.current.velocity - omega * combined * dt) * decay;
      paint();
      if (Math.abs(motion.current.position - target) < 0.001 && Math.abs(motion.current.velocity) < 0.01) snap();
      else frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    const reduce = () => { if (media?.matches) snap(); };
    media?.addEventListener('change', reduce);
    return () => { cancelAnimationFrame(frame); media?.removeEventListener('change', reduce); };
  }, [digit, active]);
  return <span className="cs-number-digit"><span className="cs-number-track" ref={track}>{Array.from({ length: 10 }, (_, number) => <span key={number}>{number}</span>)}</span></span>;
}

export function AnimatedNumber({ value }: { value: number | string }) {
  const root = useRef<HTMLSpanElement>(null);
  const [active, setActive] = useState(false);
  const text = String(value);
  useEffect(() => {
    if (!root.current || typeof IntersectionObserver === 'undefined') { setActive(true); return; }
    const observer = new IntersectionObserver(entries => {
      if (entries.some(entry => entry.isIntersecting)) { setActive(true); observer.disconnect(); }
    }, { threshold: 0.2 });
    observer.observe(root.current);
    return () => observer.disconnect();
  }, []);
  return <span ref={root} className="cs-animated-number" role="img" aria-label={text}><span aria-hidden="true" className="cs-number-visual">{Array.from(text).map((character, index) => /[0-9]/.test(character) ? <RollingDigit key={text.length - index} digit={Number(character)} active={active} /> : <span className="cs-number-symbol" key={text.length - index}>{character}</span>)}</span></span>;
}

"use client";
import { useEffect, useId, useRef, useState } from 'react';
export interface ChartDatum { label: string; x?: number; values: Record<string, number | null> }
export interface ChartSeries { key: string; label: string; color?: string; channel?: number }
export interface ChartProps {
  title: string; description?: string; data: ChartDatum[]; series: ChartSeries[]; unit?: string;
  height?: number; loading?: boolean; barBaseline?: number; minorGrid?: boolean;
  xScale?: 'category'|'linear'|'log'; xLabel?: string; yLabel?: string;
  xDomain?: [number, number]; yDomain?: [number, number]; yStep?: number; measurementInfo?: string[];
}
function spacedTicks(values: number[], position: (value: number) => number, minimumGap: number) {
  if (values.length < 2) return values;
  const result = [values[0]];
  for (const value of values.slice(1, -1)) {
    if (Math.abs(position(value) - position(result[result.length - 1])) >= minimumGap) result.push(value);
  }
  const last = values[values.length - 1];
  if (result.length > 1 && Math.abs(position(last) - position(result[result.length - 1])) < minimumGap) result.pop();
  result.push(last);
  return result;
}
export const chartChannelColors: readonly string[] = Object.freeze(Array.from({length:64},(_,index)=>`var(--cs-chart-channel-${String(index+1).padStart(2,'0')})`));
export function LineChart(props:ChartProps) {return <Chart {...props} kind="line"/>;}
export function BarChart(props:ChartProps) {return <Chart {...props} kind="bar"/>;}
function Chart({title,description,data,series,unit='',height=300,loading=false,barBaseline=0,xScale='category',xLabel,yLabel,xDomain,yDomain,yStep,measurementInfo,minorGrid=true,kind}:ChartProps&{kind:'line'|'bar'}) {
  const id=useId();const [active,setActive]=useState<number | undefined>(undefined);const [hidden,setHidden]=useState<string[]>([]);
  const visible=series.filter(item=>!hidden.includes(item.key));
  const values=data.flatMap(row=>visible.map(item=>row.values[item.key])).filter((n):n is number=>typeof n==='number'&&Number.isFinite(n));
  const plot = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(960);
  useEffect(() => {
    if (!plot.current) return;
    const element = plot.current;
    const measure = () => setWidth(Math.max(320, Math.round(element.getBoundingClientRect().width)));
    measure(); const observer = new ResizeObserver(measure); observer.observe(element);
    return () => observer.disconnect();
  }, []);
  const low=Math.min(0,...values), high=Math.max(0,...values);
  const rough=(high-low||10)/5, power=10**Math.floor(Math.log10(rough));
  const stepY=yStep&&Number.isFinite(yStep)&&yStep>0?yStep:([1,2,5,10].find(n=>n*power>=rough)??10)*power;
  const validDomain=yDomain&&Number.isFinite(yDomain[0])&&Number.isFinite(yDomain[1])&&yDomain[1]>yDomain[0];
  const min=validDomain?yDomain[0]:Math.floor(low/stepY)*stepY;
  const max=validDomain?yDomain[1]:Math.max(min+stepY,Math.ceil(high/stepY)*stepY);
  const ticks=Array.from({length:Math.min(100,Math.floor((max-min)/stepY)+1)},(_,i)=>min+i*stepY);
  const top=12,left=76,right=16,bottom=54,svgHeight=Math.max(180,height),plotHeight=svgHeight-top-bottom,plotWidth=width-left-right;
  const y=(value:number)=>top+plotHeight-(value-min)/(max-min)*plotHeight;
  const step=plotWidth/Math.max(1,data.length);
  const numeric=xScale!=='category'&&data.every(row=>Number.isFinite(row.x)&& (xScale!=='log'||row.x!>0));
  const transformX=(n:number)=>xScale==='log'?Math.log10(n):n;
  const validXDomain=xDomain&&Number.isFinite(xDomain[0])&&Number.isFinite(xDomain[1])&&xDomain[1]>xDomain[0]&&(xScale!=='log'||xDomain[0]>0);
  const xMin=validXDomain?transformX(xDomain[0]):numeric&&data.length?Math.min(...data.map(row=>transformX(row.x!))):0;
  const xMax=validXDomain?transformX(xDomain[1]):numeric&&data.length?Math.max(...data.map(row=>transformX(row.x!))):10;
  const x=(i:number)=>numeric?(xMax===xMin?left+plotWidth/2:left+(transformX(data[i].x!)-xMin)/(xMax-xMin)*plotWidth):left+step*(i+.5);
  const xTicks=numeric&&xScale==='log'?[20,50,100,200,500,1000,2000,5000,10000,20000].filter(n=>transformX(n)>=xMin&&transformX(n)<=xMax):numeric&&xScale==='linear'?Array.from({length:5},(_,i)=>xMin+(xMax-xMin)*i/4):[];
  const displayedYTicks = spacedTicks(ticks, y, 44);
  const displayedXTicks = spacedTicks(xTicks, value => left+(transformX(value)-xMin)/(xMax-xMin||1)*plotWidth, 72);
  const minorYPositions = displayedYTicks.slice(0,-1).map((value,index) => (y(value)+y(displayedYTicks[index+1]))/2);
  const minorXPositions = displayedXTicks.slice(0,-1).flatMap((value,index) => {
    const start = left+(transformX(value)-xMin)/(xMax-xMin||1)*plotWidth;
    const end = left+(transformX(displayedXTicks[index+1])-xMin)/(xMax-xMin||1)*plotWidth;
    if (end-start < 120) return [];
    const divisions = Math.min(4, Math.max(2, Math.floor((end-start)/150)));
    return Array.from({length:divisions-1},(_,part)=>start+(end-start)*(part+1)/divisions);
  });
  const categoryStride = Math.max(1, Math.ceil(data.length / Math.max(1, Math.floor(plotWidth / 72))));
  const hitLeft=(i:number)=>i===0?left:(x(i-1)+x(i))/2;
  const hitRight=(i:number)=>i===data.length-1?width-right:(x(i)+x(i+1))/2;
  const color=(item:ChartSeries)=>item.color??chartChannelColors[Number.isInteger(item.channel)&&item.channel!>=1&&item.channel!<=64?item.channel!-1:series.indexOf(item)%chartChannelColors.length];
  const selected=active===undefined?undefined:data[active];
  const cursorFormat=(n:number)=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:3}).format(n);
  const cursorValue=selected?visible.map(item=>selected.values[item.key]).find((value):value is number=>typeof value==='number'&&Number.isFinite(value)):undefined;
  const cursorY=cursorValue===undefined?top:Math.min(top+plotHeight,Math.max(top,y(cursorValue)));
  const format=(n:number)=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2,notation:Math.abs(n)>=10000?'compact':'standard'}).format(n);
  return <figure className="cs-chart" aria-labelledby={`${id}-title`}>
    <figcaption><strong id={`${id}-title`}>{title}</strong>{description&&<p>{description}</p>}</figcaption>
    {measurementInfo&&<div className="cs-chart-measurement-info">{measurementInfo.map(info=><span key={info}>{info}</span>)}</div>}
    <div className="cs-chart-legend" role="group" aria-label={`${title} 数据序列`}>{series.map(item=><button key={item.key} type="button" aria-pressed={!hidden.includes(item.key)} onClick={()=>setHidden(current=>current.includes(item.key)?current.filter(key=>key!==item.key):[...current,item.key])}><span style={{background:color(item)}}/>{item.label}</button>)}</div>
    <>
      <div ref={plot} className="cs-chart-plot" onMouseLeave={()=>setActive(undefined)}>
        <svg viewBox={`0 0 ${width} ${svgHeight}`} width="100%" height={svgHeight} role="img" aria-label={`${title}，${kind==='line'?'折线图':'柱状图'}，${data.length} 组数据；详细数值见下方数据表`}>
          <defs><clipPath id={`${id}-clip`}><rect x={left} y={top} width={plotWidth} height={plotHeight}/></clipPath></defs>
          <text x={20} y={top+plotHeight/2} transform={`rotate(-90 20 ${top+plotHeight/2})`} textAnchor="middle" fill="var(--cs-chart-axis)" fontSize="var(--cs-text-xs)">{yLabel??unit}</text>
          <text x={left+plotWidth/2} y={svgHeight-10} textAnchor="middle" fill="var(--cs-chart-axis)" fontSize="var(--cs-text-xs)">{xLabel}</text>
          <rect x={left} y={top} width={plotWidth} height={plotHeight} fill="var(--cs-chart-plot-bg)" stroke="var(--cs-chart-grid)"/>
          {minorGrid && minorXPositions.map((xx,index)=><line key={`minor-x-${index}`} data-grid="minor-x" x1={xx} x2={xx} y1={top} y2={top+plotHeight} stroke="var(--cs-chart-grid)" strokeWidth=".5" opacity=".65"/>)}
          {minorGrid && minorYPositions.map((yy,index)=><line key={`minor-y-${index}`} data-grid="minor-y" x1={left} x2={width-right} y1={yy} y2={yy} stroke="var(--cs-chart-grid)" strokeWidth=".5" opacity=".65"/>)}
          {displayedYTicks.map(value=>{const yy=y(value);return <g key={value} data-axis-tick="y"><line x1={left} x2={width-right} y1={yy} y2={yy} stroke="var(--cs-chart-grid)" strokeWidth=".75"/><text x={left-10} y={yy+4} textAnchor="end" fill="var(--cs-chart-axis)" fontSize="var(--cs-text-xs)">{format(value)}</text></g>;})}
          {displayedXTicks.map(value=>{const xx=left+(transformX(value)-xMin)/(xMax-xMin)*plotWidth;return <g key={value} data-axis-tick="x"><line x1={xx} x2={xx} y1={top} y2={top+plotHeight} stroke="var(--cs-chart-grid)" strokeWidth=".75"/><text x={xx} y={top+plotHeight+20} textAnchor="middle" fill="var(--cs-chart-axis)" fontSize="var(--cs-text-xs)">{value>=1000?`${value/1000}k`:format(value)}</text></g>;})}
          {selected&&active!==undefined&&!loading&&<g className="cs-chart-crosshair" clipPath={`url(#${id}-clip)`} pointerEvents="none">
            <line x1={x(active)} x2={x(active)} y1={top} y2={top+plotHeight}/>
            {visible.map(item=>{const value=selected.values[item.key];return typeof value==='number'&&Number.isFinite(value)?<line key={item.key} x1={left} x2={width-right} y1={y(value)} y2={y(value)}/>:null;})}
          </g>}
          {min<0&&max>=0&&<line x1={left} x2={width-right} y1={y(0)} y2={y(0)} stroke="var(--cs-chart-axis)" clipPath={`url(#${id}-clip)`}/>}
          {!loading&&kind==='line'&&visible.map(item=>{let path='';let connected=false;data.forEach((row,i)=>{const n=row.values[item.key];if(typeof n!=='number'||!Number.isFinite(n)){connected=false;return;}path+=`${connected?'L':'M'}${x(i)},${y(n)} `;connected=true;});return <path key={item.key} d={path} fill="none" stroke={color(item)} strokeWidth="1.5" strokeLinejoin="round" clipPath={`url(#${id}-clip)`}/>;})}
          {!loading&&data.map((row,i)=><g key={`${row.label}-${i}`}>
            {(!xTicks.length&&i%categoryStride===0)&&<text x={x(i)} y={top+plotHeight+24} textAnchor="middle" fill="var(--cs-chart-axis)" fontSize="var(--cs-text-xs)">{row.label.length>10?row.label.slice(0,9)+'…':row.label}</text>}
            {visible.map((item,j)=>{const n=row.values[item.key];if(typeof n!=='number'||!Number.isFinite(n))return null;const barWidth=Math.min(36,step*.7/Math.max(1,visible.length));return kind==='bar'?<rect key={item.key} x={x(i)-visible.length*barWidth/2+j*barWidth} y={Math.min(y(Number.isFinite(barBaseline)?barBaseline:0),y(n))} width={Math.max(1,barWidth-3)} height={Math.max(1,Math.abs(y(n)-y(Number.isFinite(barBaseline)?barBaseline:0)))} clipPath={`url(#${id}-clip)`} rx="0" fill={color(item)} opacity={active===undefined||active===i?1:.55}/>:active===i?<circle key={item.key} cx={x(i)} cy={y(n)} r="5" fill={color(item)} stroke="#334155" strokeWidth="1.5"/>:null;})}
            <rect x={hitLeft(i)} y={top} width={Math.max(1,hitRight(i)-hitLeft(i))} height={plotHeight} fill="transparent" tabIndex={0} role="button" aria-label={`${row.label}：${visible.map(item=>`${item.label} ${typeof row.values[item.key]==='number'?row.values[item.key]:'无数据'} ${unit}`).join('，')}`} onMouseEnter={()=>setActive(i)} onMouseMove={()=>setActive(i)} onFocus={()=>setActive(i)} onBlur={()=>setActive(undefined)} onKeyDown={event=>{if(event.key==='Escape'){setActive(undefined);return;}if(event.key==='Enter'||event.key===' '){event.preventDefault();setActive(i);return;}if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();const next=event.key==='ArrowRight'?event.currentTarget.parentElement?.nextElementSibling:event.currentTarget.parentElement?.previousElementSibling;next?.querySelector<SVGRectElement>('[role="button"]')?.focus();}}}/>
          </g>)}
        </svg>
        {selected&&active!==undefined&&!loading&&visible.length>0&&<div className="cs-chart-tooltip" aria-hidden="true" data-flip={x(active)>left+plotWidth*.6||undefined} style={{left:`${x(active)/width*100}%`,top:`${Math.min(svgHeight-110,Math.max(8,cursorY-36))}px`}}>
          <div className="cs-chart-tooltip-title">{typeof selected.x==='number'&&xLabel?.includes('Hz')?`${cursorFormat(selected.x)} Hz`:selected.label}</div>
          {visible.map(item=><div className="cs-chart-tooltip-row" key={item.key}><span className="cs-chart-tooltip-dot" style={{background:color(item)}}/><span>{item.label}</span><strong>{typeof selected.values[item.key]==='number'&&Number.isFinite(selected.values[item.key])?cursorFormat(selected.values[item.key]!):'—'} {unit}</strong></div>)}
        </div>}
        {(loading||!data.length||!series.length)&&<div className="cs-chart-overlay" role={loading?'status':undefined}><span>{loading?'正在加载图表…':'暂无图表数据'}</span></div>}
      </div>
      {!loading&&data.length>0&&series.length>0&&<><div className="cs-sr-only" aria-live="polite" aria-atomic="true">{selected?<><strong>{selected.label}</strong>{visible.map(item=><span key={item.key}>{item.label}：{typeof selected.values[item.key]==='number'?cursorFormat(selected.values[item.key]!):'—'} {unit}</span>)}</>:<span>移动鼠标查看数值 · Tab / 方向键移动 · Esc 隐藏{unit?` · 单位 ${unit}`:''}</span>}</div>
      <details className="cs-chart-data"><summary>查看数据表</summary><div className="cs-table-scroll"><table className="cs-table"><caption className="cs-sr-only">{title}原始数据</caption><thead><tr><th>项目</th>{series.map(item=><th key={item.key}>{item.label}{unit?` (${unit})`:''}</th>)}</tr></thead><tbody>{data.map((row,i)=><tr key={i}><th scope="row">{row.label}</th>{series.map(item=><td key={item.key}>{typeof row.values[item.key]==='number'&&Number.isFinite(row.values[item.key])?format(row.values[item.key]!):'—'}</td>)}</tr>)}</tbody></table></div></details></>}
    </>
  </figure>;
}

"use client";
import { useEffect, useRef, useState } from 'react';
import { HexColorPicker } from 'react-colorful';
import { Tabs, TabsList, TabsTrigger, TabsContent } from './navigation';
export interface ColorFill {
  mode: 'solid' | 'gradient' | 'image';
  color: string;
  opacity: number;
  endColor: string;
  angle: number;
  imageUrl?: string;
}
export interface ColorPickerProps {
  value?: ColorFill;
  defaultValue?: Partial<ColorFill>;
  onChange?: (fill: ColorFill) => void;
  disabled?: boolean;
  onClose?: () => void;
}
const defaults: ColorFill = { mode:'solid',color:'#170057',opacity:100,endColor:'#a855f7',angle:90 };
const validHex = (text: string) => /^#[0-9a-f]{6}$/i.test(text);
export function colorFillBackground(fill: ColorFill): string {
  const color=validHex(fill.color)?fill.color:defaults.color;
  const end=validHex(fill.endColor)?fill.endColor:defaults.endColor;
  return fill.mode==='gradient' ? `linear-gradient(${Number.isFinite(fill.angle)?fill.angle:90}deg, ${color}, ${end})` : color;
}
export function ColorPicker({value,defaultValue,onChange,disabled=false,onClose}:ColorPickerProps) {
  const [internal,setInternal]=useState<ColorFill>({...defaults,...defaultValue});
  const fill=value??internal;
  const [draft,setDraft]=useState(fill.color);
  const [error,setError]=useState('');
  const [message,setMessage]=useState('');
  const [saved,setSaved]=useState(['#16a34a','#2563eb','#4f46e5','#9333ea','#db2777','#dc2626','#ea580c','#170057']);
  const localImage=useRef<string | undefined>(undefined);
  useEffect(()=>{setDraft(fill.color);},[fill.color]);
  useEffect(()=>()=>{if(localImage.current)URL.revokeObjectURL(localImage.current);},[]);
  function update(patch:Partial<ColorFill>) { if(disabled)return;const next={...fill,...patch};setInternal(next);onChange?.(next);setError(''); }
  async function eyedrop() {
    const ctor=(window as unknown as {EyeDropper?:new()=>{open:()=>Promise<{sRGBHex:string}>}}).EyeDropper;
    if(!ctor){setMessage('此浏览器不支持屏幕取色，请使用色板或 Hex 输入。');return;}
    try { const result=await new ctor().open();update({color:result.sRGBHex}); } catch {setMessage('已取消取色。');}
  }
  return <div className="cs-color-picker">
    {onClose && <button type="button" className="cs-color-close" aria-label="关闭颜色选择器" onClick={onClose}><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.2" strokeLinecap="round" aria-hidden="true"><path d="m6 6 12 12M18 6 6 18"/></svg></button>}
    <fieldset disabled={disabled} className="cs-color-fieldset">
      <legend className="cs-sr-only">填充颜色</legend>
      <Tabs value={fill.mode} onValueChange={mode=>update({mode:mode as ColorFill['mode']})}>
        <TabsList aria-label="填充类型"><TabsTrigger value="solid" disabled={disabled}>Solid</TabsTrigger><TabsTrigger value="gradient" disabled={disabled}>Gradient</TabsTrigger><TabsTrigger value="image" disabled={disabled}>Image</TabsTrigger></TabsList>
        <TabsContent value="solid"><HexColorPicker color={validHex(fill.color)?fill.color:defaults.color} onChange={color=>update({color})} aria-label="选择纯色" /></TabsContent>
        <TabsContent value="gradient"><div className="cs-color-gradient-preview" style={{background:colorFillBackground(fill)}} /><div className="cs-color-gradient-inputs"><label>起始色<input type="color" aria-label="渐变起始色" value={fill.color} onChange={e=>update({color:e.target.value})} /></label><label>结束色<input type="color" aria-label="渐变结束色" value={fill.endColor} onChange={e=>update({endColor:e.target.value})} /></label><label>角度<input type="number" aria-label="渐变角度" min="0" max="360" value={fill.angle} onChange={e=>update({angle:Math.max(0,Math.min(360,Number(e.target.value)))})} /></label></div></TabsContent>
        <TabsContent value="image"><div className="cs-color-image-preview">{fill.imageUrl?<img src={fill.imageUrl} alt="填充图片预览" onError={()=>setError('图片无法显示，请重新选择。')} />:<span>选择一张图片作为填充</span>}</div><label className="cs-field">图片文件<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={e=>{const file=e.target.files?.[0];if(!file)return;if(!/^image\/(png|jpeg|webp|gif)$/.test(file.type)||file.size>10*1024*1024){setError('请选择不超过 10 MB 的 PNG、JPG、WebP 或 GIF。');return;}if(localImage.current)URL.revokeObjectURL(localImage.current);localImage.current=URL.createObjectURL(file);update({imageUrl:localImage.current});}} /></label><p className="cs-help">仅在本地预览，最多 10 MB；持久化图片由消费项目处理。</p></TabsContent>
      </Tabs>
      <div className="cs-color-opacity"><button type="button" aria-label="屏幕取色" onClick={()=>void eyedrop()} disabled={disabled || fill.mode==='image'}><svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" aria-hidden="true"><path d="m15 4 5 5M4 20l3-1L20 6a2 2 0 0 0-3-3L4 16Z" /></svg></button><label>透明度 {fill.opacity}%<input type="range" aria-label="透明度" min="0" max="100" value={fill.opacity} onChange={e=>update({opacity:Number(e.target.value)})} /></label></div>
      {fill.mode!=='image' && <div className="cs-color-hex-row"><span>Hex</span><span className="cs-color-dot" style={{background:fill.color}} /><input aria-label="Hex 颜色" value={draft} aria-invalid={!!error} onChange={e=>{setDraft(e.target.value);if(validHex(e.target.value))update({color:e.target.value});}} onBlur={()=>{if(!validHex(draft))setError('请输入完整的六位 Hex 色值，例如 #170057。');}} /><label><input type="number" aria-label="透明度百分比" min="0" max="100" value={fill.opacity} onChange={e=>update({opacity:Math.max(0,Math.min(100,Number(e.target.value)))})} />%</label></div>}
      {error && <p role="alert" className="cs-error">{error}</p>}
      <div className="cs-color-saved-heading"><strong>Saved</strong><button type="button" disabled={fill.mode==='image'} onClick={()=>{if(validHex(fill.color)){setSaved(current=>Array.from(new Set([...current,fill.color])).slice(-16));setMessage('当前颜色已加入本次会话色板。');}}}>＋ Add</button></div>
      <div className="cs-color-swatches" role="group" aria-label="保存的颜色">{saved.map(color=><button key={color} type="button" aria-label={`选择 ${color}`} aria-pressed={fill.color.toLowerCase()===color.toLowerCase()} style={{background:color}} onClick={()=>update({color})} />)}</div>
      <span className="cs-help" role="status">{message}</span>
    </fieldset>
  </div>;
}

"use client";
import { useState, type ReactNode } from 'react';
import { Command } from 'cmdk';
import * as Dialog from '@radix-ui/react-dialog';
export interface CommandMenuItem {
  id: string;
  label: string;
  description?: string;
  icon?: ReactNode;
  shortcut?: string;
  keywords?: string[];
  disabled?: boolean;
  onSelect?: () => void;
}
export interface CommandMenuGroup { id: string; label: string; items: CommandMenuItem[] }
export interface CommandMenuProps {
  groups: CommandMenuGroup[];
  title?: string;
  placeholder?: string;
  emptyText?: string;
  trigger?: ReactNode;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  onSelect?: (id: string) => void;
