.cs-color-picker .cs-tabs-list { gap: 4px; }
.cs-color-picker .cs-tabs-trigger { padding: 8px 10px; }
.cs-color-picker .cs-tabs-content { padding-top: 16px; }
.cs-color-picker .react-colorful { width: 100%; height: 240px; }
.cs-color-picker .react-colorful__saturation { border-radius: 8px; border-bottom: 0; }
.cs-color-picker .react-colorful__hue { margin-top: 16px; height: 12px; border-radius: 99px; }
.cs-color-picker .react-colorful__pointer { width: 18px; height: 18px; }
.cs-color-gradient-preview, .cs-color-image-preview { width: 100%; height: 180px; border-radius: 8px; overflow: hidden; background: var(--cs-subtle); display: grid; place-items: center; font-size: 14px; }
.cs-color-image-preview img { width: 100%; height: 100%; object-fit: cover; }
.cs-color-gradient-inputs { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 8px; margin-top: 12px; }
.cs-color-gradient-inputs label { display: grid; gap: 4px; font-size: 12px; }
.cs-color-gradient-inputs input { font: inherit; width: 100%; min-width: 0; height: 32px; box-sizing: border-box; border: 1px solid var(--cs-border); border-radius: 4px; color: var(--cs-text); background: var(--cs-surface); }
.cs-color-opacity { display: flex; gap: 12px; margin: 16px 0; align-items: center; }
.cs-color-opacity button { width: 36px; height: 36px; flex-shrink: 0; border: 1px solid var(--cs-border); border-radius: 6px; background: var(--cs-surface); color: var(--cs-muted); display: grid; place-items: center; cursor: pointer; }
.cs-color-opacity label { display: grid; gap: 4px; flex: 1; min-width: 0; font-size: var(--cs-text-xs); color: var(--cs-muted); }
.cs-color-opacity input { width: 100%; margin: 0; accent-color: var(--cs-brand); }
.cs-color-hex-row { display: flex; gap: 8px; align-items: center; border: 1px solid var(--cs-border); border-radius: 6px; padding: 8px; font-size: 12px; }
.cs-color-dot { width: 16px; height: 16px; flex-shrink: 0; border-radius: 50%; }
.cs-color-hex-row > input { flex: 1; width: 80px; min-width: 0; }
.cs-color-hex-row input { border: 0; background: transparent; color: var(--cs-text); font: inherit; padding: 0; }
.cs-color-hex-row label { display: flex; align-items: center; gap: 2px; }
.cs-color-hex-row label input { width: 34px; appearance: textfield; }
.cs-color-saved-heading { display: flex; justify-content: space-between; align-items: center; margin: 16px 0 12px; font-size: 14px; }
.cs-color-saved-heading strong { font-weight: var(--cs-weight-medium); }
.cs-color-saved-heading button { border: 0; padding: 0; background: transparent; color: var(--cs-muted); cursor: pointer; font: inherit; }
.cs-color-swatches { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 8px; }
.cs-color-swatches button { width: 24px; height: 24px; border: 1px solid #0001; border-radius: 50%; padding: 0; cursor: pointer; }
.cs-color-swatches button[aria-pressed="true"] { outline: 2px solid var(--cs-brand); outline-offset: 2px; }
.cs-color-close { position: absolute; top: 4px; right: 4px; border: 0; color: var(--cs-muted); background: transparent; cursor: pointer; }
.cs-color-picker :is(input,button):focus-visible { outline: 2px solid var(--cs-focus); outline-offset: 2px; }
.cs-color-picker .cs-error { font-size: 12px; }

.cs-command-menu { width: 100%; max-width: 560px; border: 1px solid var(--cs-border); border-radius: 12px; overflow: hidden; background: var(--cs-surface); color: var(--cs-text); font-family: var(--cs-font); box-shadow: var(--cs-shadow); }
.cs-command-menu-search { display: flex; align-items: center; gap: 12px; padding: 16px 20px; border-bottom: 1px solid var(--cs-border); color: var(--cs-muted); }
.cs-command-menu-search svg { flex-shrink: 0; }
.cs-command-menu-search input { flex: 1; min-width: 0; border: 0; outline: none; font: inherit; font-size: 14px; color: var(--cs-text); background: transparent; padding: 0; }
.cs-command-menu-search:focus-within { border-bottom-color: var(--cs-brand); box-shadow: none; }
.cs-command-menu kbd { font-family: inherit; white-space: nowrap; border: 1px solid var(--cs-border); border-radius: 4px; padding: 2px 5px; font-size: var(--cs-text-xs); color: var(--cs-muted); background: var(--cs-subtle); }
.cs-command-menu-list { max-height: 400px; overflow-y: auto; padding: 8px; }
.cs-command-menu-group + .cs-command-menu-group { border-top: 1px solid var(--cs-border); margin-top: 8px; padding-top: 8px; }
.cs-command-menu [cmdk-group-heading] { font-size: var(--cs-text-xs); color: var(--cs-muted); padding: 8px 12px; }
.cs-command-menu-item { display: flex; align-items: center; gap: 12px; padding: 10px 12px; border-radius: 6px;  cursor: pointer;
  font-size: var(--cs-type-control-size);
  line-height: var(--cs-type-control-leading);
}
.cs-command-menu-item[data-selected="true"] { color: var(--cs-selected-fg); background: var(--cs-selected-bg); }
.cs-command-menu-item[data-disabled="true"] { opacity: .4; cursor: not-allowed; }
.cs-command-menu-icon { display: flex; width: 20px; height: 20px; color: var(--cs-muted); flex-shrink: 0; }
.cs-command-menu-item[data-selected="true"] .cs-command-menu-icon { color: var(--cs-brand); }
.cs-command-menu-label { flex: 1; min-width: 0; display: grid; gap: 4px; }
.cs-command-menu-label small { color: var(--cs-muted);
  font-size: var(--cs-type-caption-size);
  line-height: var(--cs-type-caption-leading);
}
.cs-command-menu-empty { text-align: center; padding: 32px 16px;  color: var(--cs-muted);
  font-size: var(--cs-type-caption-size);
  line-height: var(--cs-type-caption-leading);
}
.cs-command-menu-footer { display: flex; flex-wrap: wrap; gap: 16px; padding: 12px 20px; border-top: 1px solid var(--cs-border); font-size: var(--cs-text-xs); color: var(--cs-muted); }
.cs-command-menu-dialog { position: fixed; z-index: var(--cs-z-modal); top: 18vh; left: 50%; transform: translateX(-50%); width: min(560px,calc(100vw - 32px)); outline: none; }
.cs-command-menu-dialog .cs-command-menu-list { max-height: 55vh; }

.cs-date-trigger { display: flex; align-items: center; gap: 8px; width: 100%; min-height: var(--cs-control-height); padding: 0 12px; border: 1px solid var(--cs-border); border-radius: var(--cs-radius); font: inherit;  color: var(--cs-text); background: var(--cs-surface); cursor: pointer;
  font-size: var(--cs-type-control-size);
  line-height: var(--cs-type-control-leading);
}
.cs-date-trigger span { flex: 1; text-align: left; }
.cs-date-trigger [data-placeholder] { color: var(--cs-muted); }
.cs-date-trigger svg { flex-shrink: 0; color: var(--cs-muted); }
.cs-date-trigger:focus-visible, .cs-date-trigger[data-state="open"] { outline: none; border-color: var(--cs-brand); }
.cs-date-trigger[data-state="open"] > svg:last-child { transform: rotate(180deg); color: var(--cs-brand); }
.cs-date-trigger:disabled { opacity: .5; cursor: not-allowed; }
.cs-date-trigger[aria-invalid="true"] { border-color: var(--cs-danger-fg); }
.cs-date-popover { width: 296px; max-width: calc(100vw - 24px); padding: 16px; box-sizing: border-box; border: 1px solid var(--cs-border); border-radius: 12px; background: var(--cs-surface); color: var(--cs-text); box-shadow: var(--cs-shadow); z-index: var(--cs-z-popover); font-family: var(--cs-font); }
.cs-date-header { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
.cs-date-header strong { font-size: 14px; font-weight: var(--cs-weight-medium); }
.cs-date-header button, .cs-date-grid button { display: grid; place-items: center; width: 32px; height: 32px; padding: 0; border: 0; border-radius: 50%; color: var(--cs-text); background: transparent; font: inherit; font-size: 14px; cursor: pointer; }
.cs-date-weekdays, .cs-date-grid { display: grid; grid-template-columns: repeat(7,minmax(0,1fr)); gap: 4px; }
.cs-date-weekdays { margin-bottom: 8px; color: var(--cs-muted); text-align: center; font-size: 12px; }
.cs-date-grid button { width: 100%; aspect-ratio: 1; height: auto; }
.cs-date-grid button:hover:not(:disabled) { background: var(--cs-subtle); }
.cs-date-grid button[data-outside] { color: var(--cs-muted); }
.cs-date-grid button[data-today] { box-shadow: inset 0 0 0 1px var(--cs-brand); }
.cs-date-grid button[aria-pressed="true"] { background: var(--cs-selected-bg); color: var(--cs-selected-fg); }
.cs-date-grid button:disabled { opacity: .3; cursor: not-allowed; }
.cs-date-footer { display: flex; justify-content: space-between; padding-top: 12px; margin-top: 12px; border-top: 1px solid var(--cs-border); }
.cs-date-footer button { padding: 4px 8px; border: 0; background: transparent; color: var(--cs-brand); font: inherit; font-size: 14px; cursor: pointer; }
.cs-date-footer button:disabled { opacity: .4; cursor: not-allowed; }
.cs-date-popover button:focus-visible { outline: 2px solid var(--cs-focus); outline-offset: 1px; }

.cs-upload-dropzone { border: 1px dashed var(--cs-border); border-radius: 10px; background: var(--cs-surface); }
.cs-upload-dropzone[data-dragging] { border-color: var(--cs-brand); background: var(--cs-brand-subtle); }
.cs-upload-dropzone[data-disabled] { opacity: .5; }
.cs-upload-choose { display: flex; flex-direction: column; align-items: center; gap: 12px; width: 100%; padding: 24px 16px; background: transparent; color: var(--cs-muted); border: 0; border-radius: inherit; font: inherit; font-size: 14px; cursor: pointer; }
.cs-upload-choose strong { color: var(--cs-brand); font-weight: var(--cs-weight-medium); }
.cs-upload-choose small { font-size: var(--cs-text-xs); line-height: 1.5; }
.cs-upload-choose:disabled { cursor: not-allowed; }
.cs-upload-icon { display: grid; place-items: center; width: 40px; height: 40px; border: 1px solid var(--cs-border); border-radius: 8px; color: var(--cs-text); box-shadow: var(--cs-shadow-sm); }
.cs-upload-list { list-style: none; margin: 8px 0 0; padding: 0; display: grid; gap: 12px; }
.cs-upload-list li { display: flex; align-items: flex-start; gap: 12px; padding: 16px; border: 1px solid var(--cs-border); border-radius: 8px; }
.cs-upload-file-icon { color: var(--cs-brand); flex-shrink: 0; }
.cs-upload-file-details { display: grid; gap: 4px; flex: 1; min-width: 0; }
.cs-upload-file-details strong { font-size: 14px; font-weight: var(--cs-weight-medium); overflow-wrap: anywhere; }
.cs-upload-file-details span { color: var(--cs-muted); font-size: 12px; }
.cs-upload-file-details .cs-error { color: var(--cs-danger-fg); }
.cs-upload-file-details progress { width: 100%; height: 6px; accent-color: var(--cs-brand); margin-top: 4px; }
.cs-upload-list button { display: grid; place-items: center; padding: 4px; color: var(--cs-muted); background: transparent; border: 0; cursor: pointer; font: inherit; font-size: 12px; }
.cs-upload-list button:disabled { opacity: .4; cursor: not-allowed; }
.cs-upload-field :is(button,input):focus-visible { outline: 2px solid var(--cs-brand); outline-offset: 3px; }

.cs-inline-cta { height: auto; top: auto; flex-direction: row; box-sizing: border-box; min-width: 0; display: flex; align-items: center; gap: 16px; padding: 20px 24px; border: 1px solid var(--cs-border); border-radius: var(--cs-radius-lg); background: var(--cs-surface); color: var(--cs-text); position: relative; }
.cs-inline-cta--brand { background: var(--cs-brand-subtle); border-color: color-mix(in srgb,var(--cs-brand) 20%,var(--cs-border)); }
.cs-inline-cta-icon { display: grid; place-items: center; width: 40px; height: 40px; flex-shrink: 0; border: 1px solid var(--cs-border); border-radius: 8px; background: var(--cs-surface); color: var(--cs-brand); }
.cs-inline-cta-icon svg { width: 24px; height: 24px; }
.cs-inline-cta-content { display: grid; gap: 6px; flex: 1; min-width: 0; }
.cs-inline-cta-content > strong {    color: var(--cs-text-heading);
  font-size: var(--cs-type-subsection-size);
  line-height: var(--cs-type-subsection-leading);
  font-weight: var(--cs-weight-medium);
}
.cs-inline-cta-content > div {   color: var(--cs-muted);
  font-size: var(--cs-type-body-size);
  line-height: var(--cs-type-body-leading);
}
.cs-inline-cta-actions { display: flex; gap: 8px; flex-shrink: 0; flex-wrap: wrap; }
.cs-inline-cta-actions a { box-sizing: border-box; text-decoration: none; }
.cs-inline-cta-close { display: grid; place-items: center; width: 24px; height: 24px; align-self: flex-start; border: 0; padding: 0; background: transparent; color: var(--cs-muted); cursor: pointer; flex-shrink: 0; }
.cs-inline-cta-close:focus-visible { outline: 2px solid var(--cs-focus); outline-offset: 2px; }
@media(max-width:900px) { .cs-inline-cta { flex-wrap: wrap; } .cs-inline-cta-content { flex-basis: calc(100% - 80px); } .cs-inline-cta-actions { width: 100%; } .cs-inline-cta:has(.cs-inline-cta-close) { padding-right: 44px; } .cs-inline-cta-close { position: absolute; right: 12px; top: 12px; } }
@media(max-width:540px) { .cs-inline-cta { padding: 16px; } .cs-inline-cta-actions { flex-direction: column; } .cs-inline-cta-actions .cs-button { width: 100%; } }

.cs-chart { margin: 0; padding: 16px; border: 1px solid var(--cs-border); border-radius: var(--cs-radius); background: var(--cs-surface); color: var(--cs-text); min-width: 0; }
.cs-chart figcaption > strong { font-size: 14px; font-weight: var(--cs-weight-semibold); color: var(--cs-text-heading); }
.cs-chart figcaption p { margin: 6px 0 0; color: var(--cs-muted); font-size: 12px; line-height: 20px; }
.cs-chart-legend { display: flex; gap: 20px; flex-wrap: wrap; justify-content: flex-end; margin: 12px 0 0; padding: 8px 16px 6px; background: var(--cs-chart-plot-bg); }
.cs-chart-legend button { display: flex; align-items: center; gap: 6px; padding: 0; border: 0; background: transparent; color: var(--cs-chart-axis); font: inherit; font-size: 12px; cursor: pointer; }
.cs-chart-legend button[aria-pressed="false"] { opacity: .4; text-decoration: line-through; }
.cs-chart-legend span { width: 8px; height: 8px; flex: 0 0 8px; border-radius: 0; }
.cs-chart-plot svg { display: block; overflow: visible; font-family: var(--cs-font); }
.cs-chart-plot [role="button"]:focus-visible { outline: 1px solid var(--cs-focus); outline-offset: -1px; }
.cs-chart-readout { min-height: 32px; padding: 8px 0; border-top: 1px solid var(--cs-border); border-radius: 0; background: var(--cs-surface); display: flex; align-items: center; gap: 16px; flex-wrap: wrap; font-size: 12px; color: var(--cs-muted); }
.cs-chart-readout strong { color: var(--cs-text); font-weight: var(--cs-weight-medium); }
.cs-chart-empty { display: grid; place-items: center; color: var(--cs-muted); font-size: 14px; background: var(--cs-subtle); border-radius: 6px; }
.cs-chart-data { margin-top: 16px; font-size: 12px; }
.cs-chart-data summary { cursor: pointer; color: var(--cs-brand); }
.cs-chart-data .cs-table { margin-top: 12px; }
.cs-chart-data .cs-table :is(th,td) { padding: 8px 12px; font-size: 12px; }
.cs-chart-legend button:focus-visible { outline: 2px solid var(--cs-focus); outline-offset: 4px; }
@media(max-width:540px) { .cs-chart { padding: 12px; } }

.cs-loading-indicator { --loading-size: 24px; display: inline-flex; align-items: center; gap: 10px; color: var(--cs-brand); }
.cs-loading-indicator--neutral { color: var(--cs-muted); }
.cs-loading-indicator--sm { --loading-size: 16px; gap: 8px; }
.cs-loading-indicator--lg { --loading-size: 40px; gap: 12px; }
.cs-loading-spin { width: var(--loading-size); height: var(--loading-size); flex-shrink: 0; animation: cs-loading-rotate 1s linear infinite; }
.cs-loading-label { font-size: 14px; line-height: 20px; color: var(--cs-muted); }
.cs-loading-dots { display: inline-flex; align-items: center; gap: 4px; height: var(--loading-size); }
.cs-loading-dots i { display: block; width: calc(var(--loading-size) / 4); height: calc(var(--loading-size) / 4); border-radius: 50%; background: currentColor; animation: cs-loading-bounce 1.2s ease-in-out infinite; }
.cs-loading-dots i:nth-child(2) { animation-delay: .15s; }
.cs-loading-dots i:nth-child(3) { animation-delay: .3s; }
@keyframes cs-loading-rotate { to { transform: rotate(360deg); } }
@keyframes cs-loading-bounce { 0%,60%,100% { transform: translateY(0); opacity: .4; } 30% { transform: translateY(-4px); opacity: 1; } }
@media(prefers-reduced-motion:reduce) { .cs-loading-spin, .cs-loading-dots i { animation: none; } }

.cs-progress-steps { width: 100%; }
.cs-progress-steps ol { list-style: none; display: flex; padding: 0; margin: 0; gap: 24px; }
.cs-progress-steps li { position: relative; flex: 1; min-width: 0; }
.cs-step-content { position: relative; z-index: 1; display: flex; align-items: flex-start; gap: 12px; border: 0; padding: 0; margin: 0; background: transparent; color: var(--cs-text); font: inherit; text-align: left; width: 100%; }
button.cs-step-content { cursor: pointer; }
.cs-step-marker { display: grid; place-items: center; width: 28px; height: 28px; flex: 0 0 28px; border: 1px solid var(--cs-border); border-radius: 50%; background: var(--cs-surface); color: var(--cs-muted); font-size: 12px; font-weight: var(--cs-weight-medium); box-sizing: border-box; }
.cs-step-copy { display: grid; gap: 4px; padding-top: 4px; min-width: 0; }
.cs-step-copy strong { font-size: 14px; font-weight: var(--cs-weight-medium); line-height: 20px; }
.cs-step-copy small { font-size: 12px; line-height: 18px; color: var(--cs-muted); }
.cs-progress-steps--horizontal .cs-step-content { flex-direction: column; gap: 8px; }
.cs-progress-steps li:not(:last-child)::after { content: ''; position: absolute; top: 13px; left: 40px; right: -12px; height: .5px; background: var(--cs-border); }
.cs-progress-steps li[data-state="complete"]::after { background: var(--cs-brand); }
.cs-progress-steps li[data-state="complete"] .cs-step-marker { background: var(--cs-brand); border-color: var(--cs-brand); color: var(--cs-on-brand); }
.cs-progress-steps li[data-state="current"] .cs-step-marker { border-color: var(--cs-brand); color: var(--cs-selected-fg); background: var(--cs-selected-bg); box-shadow: 0 0 0 3px var(--cs-selected-bg); }
.cs-progress-steps li[data-state="current"] strong { color: var(--cs-brand); }
.cs-progress-steps li[data-state="error"] .cs-step-marker { color: var(--cs-danger-fg); background: var(--cs-danger-bg); border-color: var(--cs-danger-fg); }
.cs-progress-steps li[data-state="error"] strong { color: var(--cs-danger-fg); }
.cs-progress-steps li[data-disabled] { opacity: .45; }
.cs-step-content:disabled { cursor: not-allowed; }
.cs-step-content:focus-visible { outline: 2px solid var(--cs-focus); outline-offset: 4px; border-radius: 4px; }
.cs-progress-steps--vertical ol { flex-direction: column; gap: 24px; }
.cs-progress-steps--vertical li:not(:last-child)::after { left: 13px; right: auto; top: 40px; bottom: -12px; width: .5px; height: auto; }
@media(max-width:600px) {
  .cs-progress-steps--horizontal ol { flex-direction: column; gap: 24px; }
  .cs-progress-steps--horizontal .cs-step-content { flex-direction: row; gap: 12px; }
  .cs-progress-steps--horizontal li:not(:last-child)::after { left: 13px; right: auto; top: 40px; bottom: -12px; width: .5px; height: auto; }
}

.cs-section-header { color: var(--cs-text); min-width: 0; }
.cs-section-header[data-divider] { border-bottom: 1px solid var(--cs-border); padding-bottom: 20px; }
.cs-section-header-main { display: flex; gap: 16px; align-items: flex-start; }
.cs-section-header-copy { display: grid; gap: 6px; flex: 1; min-width: 0; }
.cs-section-header-title { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
.cs-section-header-title :is(h2,h3,h4) { margin: 0;    color: var(--cs-text-heading); letter-spacing: normal;
  font-size: var(--cs-type-section-size);
  line-height: var(--cs-type-section-leading);
  font-weight: var(--cs-weight-semibold);
}
.cs-section-header--sm .cs-section-header-title :is(h2,h3,h4) {
  font-size: var(--cs-type-subsection-size);
  line-height: var(--cs-type-subsection-leading);
  font-weight: var(--cs-weight-medium);
}
.cs-section-header--lg .cs-section-header-title :is(h2,h3,h4) {
  font-size: var(--cs-type-page-size);
  line-height: var(--cs-type-page-leading);
  font-weight: var(--cs-weight-semibold);
}
.cs-section-header-description {   color: var(--cs-muted);
  font-size: var(--cs-type-body-size);
  line-height: var(--cs-type-body-leading);
}
.cs-section-header-eyebrow {   color: var(--cs-brand); font-weight: var(--cs-weight-medium);
  font-size: var(--cs-type-caption-size);
  line-height: var(--cs-type-caption-leading);
}
.cs-section-header-icon { display: grid; place-items: center; width: 40px; height: 40px; flex-shrink: 0; border: 1px solid var(--cs-border); border-radius: 8px; background: var(--cs-surface); color: var(--cs-brand); }
.cs-section-header-icon svg { width: 24px; height: 24px; }
.cs-section-header-actions { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; flex-shrink: 0; }
.cs-section-header-content { margin-top: 20px; }
.cs-section-header-content .cs-tabs-list { border-bottom: 0; }
@media(max-width:700px) { .cs-section-header-main { flex-wrap: wrap; } .cs-section-header-copy { flex-basis: calc(100% - 60px); } .cs-section-header-actions { width: 100%; } }

/* Inline CTA cards: reference-aligned vertical content and action hierarchy. */
.cs-inline-cta {
  display: grid; grid-template-columns: minmax(0,1fr); gap: 0;
  align-items: start; padding: 24px; border-radius: 12px;
  box-shadow: none; width: 100%;
}
.cs-inline-cta:has(.cs-inline-cta-icon) { grid-template-columns: 40px minmax(0,1fr); column-gap: 16px; }
.cs-inline-cta-content { display: grid; gap: 6px; }
.cs-inline-cta-content > strong {
  font-size: var(--cs-type-subsection-size);
  line-height: var(--cs-type-subsection-leading);
  font-weight: var(--cs-weight-medium);
}
.cs-inline-cta-content > div {
  font-size: var(--cs-type-body-size);
