  function focus(id:string){setFocused(id);requestAnimationFrame(()=>Array.from(root.current?.querySelectorAll<HTMLElement>('[role="treeitem"]')??[]).find(el=>el.dataset.id===id)?.focus());}
  function toggle(id:string){setExpanded(ids=>ids.includes(id)?ids.filter(item=>item!==id):[...ids,id]);}
  function select(node:TreeNode){if(node.disabled)return;setSelected(node.id);onSelectionChange?.(node.id);}
  function render(items:TreeNode[],level:number):ReactNode {return items.map((node,index)=>{const branch=!!node.children?.length;const isOpen=expanded.includes(node.id);return <li key={node.id} role="none"><div role="treeitem" data-id={node.id} aria-owns={branch?`${treeId}-${node.id}`:undefined} aria-level={level} aria-posinset={index+1} aria-setsize={items.length} aria-expanded={branch?isOpen:undefined} aria-selected={current===node.id} aria-disabled={!!node.disabled} tabIndex={node.id===tabId?0:-1} className="cs-tree-item" style={variant==='files'?{paddingLeft:12+(level-1)*20}:undefined} onFocus={()=>setFocused(node.id)} onClick={()=>select(node)} onDoubleClick={()=>{if(branch&&!node.disabled)toggle(node.id);}} onKeyDown={event=>{if(node.disabled)return;const index=enabled.findIndex(row=>row.node.id===node.id);const keys=['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Home','End','Enter',' '];if(keys.includes(event.key))event.preventDefault();if(event.key==='ArrowDown'&&enabled[index+1])focus(enabled[index+1].node.id);if(event.key==='ArrowUp'&&enabled[index-1])focus(enabled[index-1].node.id);if(event.key==='Home'&&enabled[0])focus(enabled[0].node.id);if(event.key==='End'&&enabled.length)focus(enabled[enabled.length-1].node.id);if(event.key==='Enter'||event.key===' ')select(node);if(event.key==='ArrowRight'&&branch){if(!isOpen)toggle(node.id);else {const child=node.children?.find(item=>!item.disabled);if(child)focus(child.id);}}if(event.key==='ArrowLeft'){if(branch&&isOpen)toggle(node.id);else {const parent=rows.find(row=>row.node.id===node.id)?.parent;if(parent)focus(parent);}}}}>
    <span className="cs-tree-toggle" aria-hidden="true" onClick={event=>{event.stopPropagation();if(branch&&!node.disabled){toggle(node.id);focus(node.id);}}}>{branch&&<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" style={{transform:isOpen?'rotate(90deg)':undefined}}><path d="m9 6 6 6-6 6"/></svg>}</span>
    <span className="cs-tree-icon" aria-hidden="true">{node.icon??<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5">{branch?<path d="M3 7V4h7l2 3h9v13H3Z"/>:<path d="M5 3h9l5 5v13H5Zm9 0v5h5"/>}</svg>}</span><span className="cs-tree-label">{node.label}</span>
    </div>{branch&&<div className="cs-tree-branch" data-open={isOpen} role="group" id={`${treeId}-${node.id}`} aria-hidden={!isOpen} inert={!isOpen}><ul role="none">{render(node.children!,level+1)}</ul></div>}</li>;});}
  return nodes.length?<ul ref={root} role="tree" aria-label={label} className={`cs-tree-view cs-tree-view--${variant}`}>{render(nodes,1)}</ul>:<div className="cs-tree-empty">暂无目录内容</div>;
}

