  --cs-type-intro-leading: 28px;
  --cs-type-section-size: 20px;
  --cs-type-section-leading: 28px;
  --cs-type-subsection-size: 16px;
  --cs-type-subsection-leading: 24px;
  --cs-type-body-size: 14px;
  --cs-type-body-leading: 22px;
  --cs-type-lead-size: 16px;
  --cs-type-lead-leading: 26px;
  --cs-type-caption-size: 12px;
  --cs-type-caption-leading: 18px;
  --cs-type-label-size: 14px;
  --cs-type-label-leading: 20px;
}

/* Dense controls may follow density; reading content keeps its role sizes. */
:root, [data-theme], [data-customer], [data-density] {
  --cs-type-control-size: var(--cs-font-size);
  --cs-type-control-leading: 20px;
}
